import {eqsStageSummary} from './eqs-debug-stages.js';

export function renderEqsDebugControls(form,doc,hooks){
 const document=form.ownerDocument,section=document.createElement('section'),controls=document.createElement('div'),target=document.createElement('select'),run=document.createElement('button'),hide=document.createElement('button'),stage=document.createElement('select'),status=document.createElement('output');
 doc.view??={};const state=doc.view.eqs??={labels:true,failed:true,stage:'final'},checks=new Map();let report=null,serial=0;
 const live=()=>section.isConnected,options=()=>({labels:checks.get('labels').checked,failed:checks.get('failed').checked,stage:stage.value==='final'||stage.value==='projection'?stage.value:Number(stage.value)});
 target.dataset.eqsTarget='';target.setAttribute('aria-label','질의 대상');const world=hooks.world();for(const object of world.objects.filter(o=>!['component','widget'].includes(o.kind))){const option=document.createElement('option');option.value=object.id;option.textContent=object.name;target.append(option);}target.value=[state.target,world.selected].find(id=>[...target.options].some(o=>o.value===id))||target.options[0]?.value||'';
 stage.dataset.eqsStage='';stage.setAttribute('aria-label','표시 단계');
 const stages=data=>{stage.replaceChildren();for(const [value,label]of [['final','최종 결과'],['projection','투영 후'],...(data?.tests||[]).map(test=>[String(test.index),(test.index+1)+'. '+test.type])]){const option=document.createElement('option');option.value=value;option.textContent=label;stage.append(option);}stage.value=[...stage.options].some(o=>o.value===String(state.stage))?String(state.stage):'final';stage.disabled=!data;};
 const summary=()=>{if(!report){status.replaceChildren();return;}const selected=eqsStageSummary(report,options().stage),line=document.createElement('div'),tests=document.createElement('div');line.textContent=selected.generated+' 후보 · '+selected.matched+' 통과 · '+selected.failed+' 실패 · 전체 '+Number(report.durationMS.toFixed(2))+' ms'+(report.truncated?' · 진단 '+report.total+'/'+report.generated:'');for(const test of report.tests){const button=document.createElement('button');button.type='button';button.dataset.eqsTestStage=String(test.index);button.setAttribute('aria-pressed',String(options().stage===test.index));button.textContent=(test.index+1)+'. '+test.type+' · '+test.passed+'/'+test.input;button.onclick=()=>{stage.value=String(test.index);view();};tests.append(button);}status.replaceChildren(line,tests);};
 const view=()=>{if(!report)return;try{const value=options();hooks.queryView(target.value,value);Object.assign(state,value);summary();}catch(error){hooks.error(error.message);}};
 run.type=hide.type='button';run.textContent='질의 실행 · 시각화';run.dataset.eqsRun='';hide.textContent='숨기기';
 run.onclick=async()=>{const request=++serial,id=target.value;run.disabled=true;try{const data=await hooks.query({asset:doc.path,target:id,visualize:false,labels:checks.get('labels').checked,failed:checks.get('failed').checked});if(!live()||request!==serial||target.value!==id)return;report=data;state.target=id;stages(data);view();}catch(error){if(live()&&request===serial)hooks.error(error.message);}finally{if(live())run.disabled=false;}};
 hide.onclick=()=>{try{hooks.queryView(target.value,{enabled:false});serial++;report=null;stages(null);summary();}catch(error){hooks.error(error.message);}};
 target.onchange=()=>{serial++;state.target=target.value;state.stage='final';report=null;stages(null);summary();};stage.onchange=view;
 for(const [key,label]of [['labels','점수'],['failed','실패 후보']]){const row=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=state[key]!==false;check.dataset.eqsView=key;check.onchange=()=>{state[key]=check.checked;view();};checks.set(key,check);row.append(check,label);controls.append(row);}
 const stageLabel=document.createElement('label');stageLabel.append('표시 단계',stage);controls.prepend(target,run,hide,stageLabel);section.className='eqs-debug-controls';status.dataset.eqsSummary='';section.append(controls,status);form.append(section);stages(null);return section;
}
